  /** Specify the Blueprint ID, which starts with exs-. Use the Blueprint ID, not a sync ID. */
  blueprintId: string,
  /** Provide values for the environment variables listed in sync.requiredManualEnvVars. */
  manualEnvVars?: Array<{
