      serviceType: "web" | "pserv" | "worker" | "cron" | "workflow" | "buildSource",
      /** Provide the exact environment variable value. An empty string is allowed. */
      value: string,
    }>,
  /** The ID of the Render workspace to use. Reuse the workspaceId the user confirmed from list_workspaces. */
  workspaceId?: string,
}): Promise<unknown> // This tool is in public alpha (early access). Access to this tool and its contract are subject to change. Approve and apply the Blueprint's newest planned sync after confirming that planning succeeded. Approval can update existing resources. After the first approval, Git pushes apply changes automatically when autoSync is enabled. Manually requested plans require approval even when autoSync is enabled. Call approve_blueprint only after the user authorizes applying the reviewed plan. Providing ...
  - tools.render.cancel_cron_job_run({
  /** The ID of the cron job whose run to cancel (starts with crn-). */
  serviceId: string,
  /** The ID of the Render workspace to use. Reuse the workspaceId the user confirmed from list_workspaces. */
  workspaceId?: string,
}): Promise<unknown> // Cancel the in-progress run of a cron job. Canceling stops the run partway, which can leave its work half done, so confirm with the user first. It does not pause the schedule: the next scheduled run still starts on time. Afterward, list_events with eventTypes cron_job_run_ended shows the run as canceled.
  - tools.render.cancel_flow_run({
  /** Exact ID of the flow run to cancel in the selected workspace */
  flowRunId: string,
  /** The ID of the Render workspace to use. Reuse the workspaceId the user confirmed from list_workspaces. */
  workspaceId?: string,
}): Promise<unknown> // Request cancellation of a pending or running flow run. Cancellation stops the flow and cannot be undone. Returns once the request is accepted; poll get_flow_run until the status is canceled.

