  ok: true,
  schemaVersion: 1,
  sessionId: 'session-1',
  gamesDigest: 'a'.repeat(64),
  coveragePct: 82,
  baselineBpm: 70,
  verdict: 'One steady game.',
  settled: { band: 'settled', moves: 30, status: 'ok', accuracy: 71 },
  elevated: { band: 'elevated', moves: 12, status: 'ok', accuracy: 54 },
