// What: the three framing checks Setup shows, derived from the SDK's one active validation code.
// Why: Setup must name what to fix before a session, using the same hints the sensing screen gets.
// Removed: framing advice would exist only in the README, and Start could open a session that measures nothing.

/** The SDK's integer validation codes. Values are stable across SDK versions. */
export const VALIDATION = {
  ok: 0,
  noFaceFound: 1,
  multipleFacesFound: 2,
  faceNotCentered: 3,
  faceSizeOutOfRange: 4,
  tooDark: 5,
  tooBright: 6,
  chestNotVisible: 7,
  cameraTuning: 10,
  frameRateTooLow: 11,
  excessiveMotion: 12,
  faceTooClose: 13,
  faceTooFar: 14,
  faceTooHigh: 15,
  faceTooLow: 16,
  faceNotForward: 17,
} as const;

export type FramingState = 'unknown' | 'pass' | 'fail';

export interface FramingChecks {
  face: FramingState;
  chest: FramingState;
  light: FramingState;
}

export const UNKNOWN_FRAMING: FramingChecks = {
  face: 'unknown',
  chest: 'unknown',
  light: 'unknown',
};

const FACE_CODES = new Set<number>([
  VALIDATION.noFaceFound,
  VALIDATION.multipleFacesFound,
  VALIDATION.faceNotCentered,
  VALIDATION.faceSizeOutOfRange,
  VALIDATION.faceTooClose,
  VALIDATION.faceTooFar,
  VALIDATION.faceTooHigh,
  VALIDATION.faceTooLow,
  VALIDATION.faceNotForward,
]);

const LIGHT_CODES = new Set<number>([VALIDATION.tooDark, VALIDATION.tooBright]);

/**
 * The SDK reports one current code, not three independent booleans. A code that fixes one check
 * leaves the others unknown rather than borrowing an old pass from a different frame.
 */
export function framingFromValidation(code: number): FramingChecks {
  if (code === VALIDATION.ok) {
    return { face: 'pass', chest: 'pass', light: 'pass' };
  }
  if (code === VALIDATION.chestNotVisible) {
    return { face: 'pass', chest: 'fail', light: 'unknown' };
  }
  if (FACE_CODES.has(code)) {
    return { face: 'fail', chest: 'unknown', light: 'unknown' };
  }
  if (LIGHT_CODES.has(code)) {
    return { face: 'unknown', chest: 'unknown', light: 'fail' };
  }
  return UNKNOWN_FRAMING;
}

export function framingReady(checks: FramingChecks): boolean {
  return checks.face === 'pass' && checks.chest === 'pass' && checks.light === 'pass';
}

/** A text status per check, so the result never depends on colour alone. */
export function framingStatusText(state: FramingState): string {
  if (state === 'pass') return 'OK';
  if (state === 'fail') return 'Fix';
  return 'Waiting';
}
// What: the one gate that decides whether Setup may start a session.
// Why: consent, the key, the live preview, and all three framing checks must be named in order.
// Removed: a Start button could be disabled without telling the player which check is missing.

import { framingReady, type FramingChecks } from './framing.js';

export type KeyStatus = 'loading' | 'present' | 'missing' | 'error';
export type PreviewStatus = 'idle' | 'starting' | 'running' | 'error';

export interface SetupKeyResult {
  status: KeyStatus;
  detail: string;
}

export interface DoctorCheckLike {
  id: string;
  status: string;
  detail: string;
}

const DEFAULT_MISSING_KEY =
  'The SmartSpectra key is missing. Add SMARTSPECTRA_API_KEY to .env, then restart.';

export function keyStatusFromChecks(checks: readonly DoctorCheckLike[]): SetupKeyResult {
  const check = checks.find((candidate) => candidate.id === 'sensing-key');
  if (!check) {
    return { status: 'error', detail: 'The key check did not report a result.' };
  }
  return check.status === 'pass'
    ? { status: 'present', detail: check.detail }
    : { status: 'missing', detail: check.detail || DEFAULT_MISSING_KEY };
}

export interface SetupGateInput {
  consent: boolean;
  keyStatus: KeyStatus;
  keyDetail?: string;
  preview: PreviewStatus;
  previewError?: string | null;
  framing: FramingChecks;
}

export interface SetupGate {
  canStart: boolean;
  reasons: string[];
}

/**
 * One blocking reason at a time, in the order the player fixes them. A later check is not shown
 * as the problem while an earlier one is still missing.
 */
export function setupGate(input: SetupGateInput): SetupGate {
  if (!input.consent) {
    return { canStart: false, reasons: ['Allow the camera to continue.'] };
  }
  if (input.keyStatus === 'loading') {
    return { canStart: false, reasons: ['Checking the SmartSpectra key…'] };
  }
  if (input.keyStatus === 'missing') {
    return { canStart: false, reasons: [input.keyDetail || DEFAULT_MISSING_KEY] };
  }
  if (input.keyStatus === 'error') {
    return {
      canStart: false,
      reasons: ['The key check could not run. Open Help and copy diagnostics.'],
    };
  }
  if (input.preview === 'idle' || input.preview === 'starting') {
    return { canStart: false, reasons: ['Starting the camera preview…'] };
  }
  if (input.preview === 'error') {
    return {
      canStart: false,
      reasons: [
        input.previewError ||
          'The camera preview could not start. Check that another app is not using the camera, then try again.',
      ],
    };
  }
  if (!framingReady(input.framing)) {
    return { canStart: false, reasons: ['Framing must pass all three checks.'] };
  }
  return { canStart: true, reasons: [] };
}

