154: function placementMode(games: readonly PgnGame[]): 'endtime' | 'starttime' | 'inferred' | 'mixed' {
155:   const allEnd = games.every((game) => game.endTimeEpochMs !== undefined);
156:   const anyEnd = games.some((game) => game.endTimeEpochMs !== undefined);
