165: function unplayedTimeoutUs(game: PgnGame): number | null {
166:   if (game.ending !== 'timeout') return 0;
167:   if (game.moves.length === 0) return null;
168:   const flaggerStarts = game.moves.length % 2 === 1 ? 1 : 0;
169:   let clockSec: number | undefined;
170:   for (let index = flaggerStarts; index < game.moves.length; index += 2) {
171:     const clock = game.moves[index]?.clockSec;
172:     if (clock !== undefined) clockSec = clock;
173:   }
174:   if (clockSec === undefined) clockSec = baseSec(game.timeControl) ?? undefined;
175:   if (clockSec === undefined) return null;
176:   return Math.round(clockSec * 1_000_000);
