179: function baseSec(timeControl: string | undefined): number | null {
180:   if (timeControl === undefined) return null;
181:   const increment = /^(\d+)\+(\d+)$/.exec(timeControl);
182:   if (increment?.[1]) return Number(increment[1]);
183:   const sudden = /^(\d+)$/.exec(timeControl);
184:   if (sudden?.[1]) return Number(sudden[1]);
185:   return null;
