188: function durationUs(game: PgnGame): number | 'missing' | 'negative' {
189:   if (game.moves.length === 0) return 0;
190:   const thinks = thinkTimeSec(game);
191:   let seconds = 0;
192:   for (const think of thinks) {
193:     if (think === null) return 'missing';
194:     if (think < 0) return 'negative';
195:     seconds += think;
196:   }
197:   return Math.round(seconds * 1_000_000);
198: }
