214:     }, 'endtime', clock);
215:   }
216:   if (mode === 'starttime') {
217:     const stamped = stamp(games, durations, (game, duration) => {
218:       const startUs = monoUsFromEpochMs(clock, game.startTimeEpochMs ?? 0);
219:       return { startUs, endUs: startUs + duration, toleranceSec: STARTTIME_TOLERANCE_SEC };
220:     }, 'starttime', clock);
221:     if (!stamped.ok) return stamped;
222:     return { ok: true, games: stamped.games, banner: STARTTIME_BANNER };
223:   }
