226:   let cursor = clock.startAnchor.monoUs;
227:   const inferred = games.map((game, index) => {
228:     const duration = durations[index] ?? 0;
229:     const startUs = cursor;
230:     const endUs = cursor + duration;
231:     cursor = endUs;
232:     return aligned(game, startUs, endUs, 'inferred', 0);
233:   });
234:   if (cursor > stopUs) {
