252: function stamp(
253:   games: readonly PgnGame[],
254:   durations: readonly number[],
255:   at: (game: PgnGame, duration: number) => { startUs: number; endUs: number; toleranceSec: number },
256:   mode: 'endtime' | 'starttime',
257:   clock: SessionClock,
258: ): { ok: true; games: AlignedGame[] } | { ok: false; banner: string } {
259:   const placed = games.map((game, index) => {
260:     const span = at(game, durations[index] ?? 0);
261:     return aligned(game, span.startUs, span.endUs, mode, span.toleranceSec);
262:   });
