266: function aligned(
267:   game: PgnGame,
268:   startUs: number,
269:   endUs: number,
270:   mode: AlignedGame['alignment']['mode'],
271:   toleranceSec: number,
272: ): AlignedGame {
273:   return { game, startUs, endUs, alignment: { mode, toleranceSec } };
274: }
