276: function rejectOutside(
277:   games: readonly AlignedGame[],
278:   clock: SessionClock,
279: ): { ok: true; games: AlignedGame[] } | { ok: false; banner: string } {
280:   const recordedStart = clock.startAnchor.monoUs;
281:   const recordedStop = clock.stopAnchor?.monoUs;
282:   const outside = games.some((game) => {
283:     if (game.endUs < game.startUs) return true;
284:     if (game.startUs < recordedStart || game.endUs < recordedStart) return true;
285:     if (recordedStop !== undefined && (game.startUs > recordedStop || game.endUs > recordedStop)) return true;
286:     return false;
287:   });
288:   if (outside) {
289:     return { ok: false, banner: 'A game time falls outside the session clock, so it was not placed.' };
290:   }
291:   return { ok: true, games: [...games] };
292: }
