294: function moveTimesFor(game: AlignedGame): MoveTime[] {
295:   const thinks = thinkTimeSec(game.game);
296:   let cursor = game.startUs;
297:   return game.game.moves.map((_move, moveIndex) => {
298:     const think = thinks[moveIndex];
299:     if (think === null || think === undefined) return { gameIndex: game.game.index, moveIndex, tUs: null };
300:     cursor += Math.round(think * 1_000_000);
301:     return { gameIndex: game.game.index, moveIndex, tUs: cursor };
302:   });
303: }
