305: function betweenGameGaps(games: readonly AlignedGame[]): BetweenGameGap[] {
306:   const gaps: BetweenGameGap[] = [];
307:   for (let index = 1; index < games.length; index += 1) {
308:     const previous = games[index - 1];
309:     const current = games[index];
310:     if (!previous || !current || current.startUs <= previous.endUs) continue;
311:     gaps.push({
312:       afterIndex: previous.game.index,
313:       beforeIndex: current.game.index,
314:       fromUs: previous.endUs,
315:       toUs: current.startUs,
316:       durationUs: current.startUs - previous.endUs,
317:     });
318:   }
319:   return gaps;
320: }
321: 
322: function traceGapsFor(game: AlignedGame, samples: readonly PulseSample[]): TraceGap[] {
323:   if (game.endUs <= game.startUs) return [];
324:   const ordered = samples
325:     .filter((sample) => {
326:       if (!usable(sample) || sample.tUs > game.endUs) return false;
327:       if (sample.tUs >= game.startUs) return true;
328:       return sample.tUs + SAMPLE_HOLD_US > game.startUs;
329:     })
330:     .sort((left, right) => left.tUs - right.tUs);
331:   const gaps: TraceGap[] = [];
332:   let cursor = game.startUs;
333:   for (const sample of ordered) {
334:     if (sample.tUs > cursor) {
335:       gaps.push({
336:         gameIndex: game.game.index,
337:         fromUs: cursor,
338:         toUs: sample.tUs,
339:         durationUs: sample.tUs - cursor,
340:       });
341:     }
342:     cursor = Math.max(cursor, Math.min(game.endUs, sample.tUs + SAMPLE_HOLD_US));
343:   }
344:   if (game.endUs > cursor) {
345:     gaps.push({
346:       gameIndex: game.game.index,
347:       fromUs: cursor,
348:       toUs: game.endUs,
349:       durationUs: game.endUs - cursor,
350:     });
351:   }
352:   return gaps;
353: }
354: 
355: function usable(sample: PulseSample): boolean {
356:   return sample.stable && sample.confidence >= CONFIDENCE_FLOOR;
357: }

