import { describe, it } from 'node:test';
import type { Refusal, Report } from './contracts.js';
import { reviewStages, type StageInput } from './stages.js';

const report: Report = {
  ok: true,
  schemaVersion: 1,
  sessionId: 'session-1',
  gamesDigest: 'a'.repeat(64),
  coveragePct: 82,
