}

function isEpochUs(value: number): boolean {
  return Number.isSafeInteger(value) && value > 0;
}

function truncate(text: string): string {
  return text.length > MAX_TEXT_LENGTH ? `${text.slice(0, MAX_TEXT_LENGTH - 1)}…` : text;
}

